:root {
  color-scheme: light;
  --bg: #f3f6fb;
  --bg-strong: #e8eef8;
  --surface: rgba(255, 255, 255, 0.96);
  --surface-soft: rgba(248, 250, 252, 0.92);
  --surface-strong: #ffffff;
  --sidebar: #091629;
  --sidebar-line: rgba(148, 163, 184, 0.14);
  --ink: #142033;
  --muted: #61758d;
  --line: rgba(148, 163, 184, 0.22);
  --line-strong: rgba(148, 163, 184, 0.3);
  --brand: #2563eb;
  --brand-strong: #1d4ed8;
  --brand-soft: rgba(37, 99, 235, 0.12);
  --success: #15803d;
  --success-soft: rgba(34, 197, 94, 0.14);
  --warning: #c2410c;
  --warning-soft: rgba(249, 115, 22, 0.16);
  --danger: #dc2626;
  --danger-soft: rgba(239, 68, 68, 0.12);
  --review: #7c3aed;
  --review-soft: rgba(124, 58, 237, 0.14);
  --shadow-lg: 0 28px 60px rgba(15, 23, 42, 0.08);
  --shadow-md: 0 16px 40px rgba(15, 23, 42, 0.06);
  --radius-xl: 28px;
  --radius-lg: 22px;
  --radius-md: 18px;
}

.app-route-recovery {
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: 24px;
  color: #071735;
  background: radial-gradient(circle at top left, #eef6ff 0, #f8fbff 38%, #f4f7fb 100%);
}

.app-route-recovery section {
  display: grid;
  width: min(720px, 100%);
  gap: 16px;
  padding: 28px;
  background: #fff;
  border: 1px solid #dbe6f5;
  border-radius: 18px;
  box-shadow: 0 18px 42px rgba(15, 23, 42, .12);
}

.app-route-recovery p,
.app-route-recovery h1,
.app-route-recovery span {
  margin: 0;
}

.app-route-recovery p {
  color: #2563eb;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.app-route-recovery h1 {
  font-size: clamp(28px, 4vw, 44px);
  line-height: 1.05;
}

.app-route-recovery span {
  max-width: 58ch;
  color: #5e6b82;
  font-size: 16px;
  line-height: 1.55;
}

.app-route-recovery nav {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 8px;
}

.app-route-recovery a {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  color: #fff;
  background: #2563eb;
  border-radius: 10px;
  font-weight: 800;
  text-decoration: none;
}

.app-route-recovery a:nth-child(n+3) {
  color: #143163;
  background: #eef4ff;
  border: 1px solid #cfe0ff;
}

.concern-intake-panel {
  margin: 0 0 10px;
  padding: 14px;
}

.concern-intake-panel > header,
.concern-intake-panel footer,
.concern-preview > header,
.concern-created-state {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: space-between;
}

.concern-recent {
  border-top: 1px solid var(--line);
  margin-top: 14px;
  padding-top: 12px;
}

.concern-recent > div {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 8px;
}

.concern-recent article {
  background: #f8fafc;
  border: 1px solid #dbe4ef;
  border-radius: 10px;
  display: grid;
  font-size:11.5px;
  gap: 3px;
  padding: 9px;
}

.concern-recent article small {
  color: var(--muted);
}

.concern-intake-panel > header span,
.concern-preview p,
.concern-preview small,
.concern-created-state p {
  color: var(--muted);
  display: block;
  font-size: 12px;
  margin: 3px 0 0;
}

.concern-intake-panel form {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 12px;
}

.concern-intake-panel form > label {
  display: grid;
  font-size: 12px;
  font-weight: 700;
  gap: 5px;
}

.concern-intake-panel input,
.concern-intake-panel textarea {
  border: 1px solid var(--line);
  border-radius: 9px;
  font: inherit;
  padding: 9px;
}

.concern-wide,
.concern-checks,
.concern-preview,
.concern-intake-panel footer {
  grid-column: 1 / -1;
}

.concern-checks {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.concern-preview {
  background: #f7faff;
  border: 1px solid #cbdcf8;
  border-radius: 12px;
  padding: 12px;
}

.concern-preview ol {
  display: grid;
  gap: 5px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 10px 0;
  padding-left: 24px;
}

.concern-preview li span,
.concern-preview li small {
  display: block;
}

.concern-priority {
  border-radius: 999px;
  font-size:11.5px;
  font-weight: 800;
  padding: 6px 9px;
}

.concern-priority-high,
.concern-priority-critical,
.concern-escalation {
  color: #b42318;
}

.concern-created-state {
  justify-content: flex-start;
  padding: 18px 4px 4px;
}

@media (max-width: 900px) {
  .concern-intake-panel form,
  .concern-preview ol,
  .concern-recent > div {
    grid-template-columns: 1fr;
  }
}

/* Customer Command Center */
.app-topbar.app-topbar-customers { display: none; }
.app-topbar-customers + .app-content { padding: 0; }

.crm-mode-switch {
  align-items: center;
  background: rgba(255, 255, 255, .88);
  border: 1px solid #d9e4f3;
  border-radius: 999px;
  box-shadow: 0 10px 26px rgba(15, 42, 84, .07);
  display: inline-flex;
  flex: 0 0 auto;
  gap: 4px;
  min-width: max-content;
  padding: 4px;
}

.crm-mode-switch span {
  color: #52637a;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0;
  padding: 0 8px 0 10px;
  text-transform: uppercase;
}

.crm-mode-switch a {
  border-radius: 999px;
  color: #17345f;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  padding: 9px 12px;
  text-decoration: none;
  white-space: nowrap;
}

.crm-mode-switch details {
  position: relative;
}

.crm-mode-switch summary {
  border-radius: 999px;
  color: #52637a;
  cursor: pointer;
  display: inline-flex;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  list-style: none;
  padding: 9px 10px;
  white-space: nowrap;
}

.crm-mode-switch summary::-webkit-details-marker {
  display: none;
}

.crm-mode-switch summary:hover {
  background: #eef4ff;
  color: #0b3fb8;
}

.crm-mode-switch details > div {
  background: #ffffff;
  border: 1px solid #d9e4f3;
  border-radius: 14px;
  box-shadow: 0 18px 42px rgba(15, 42, 84, .14);
  display: grid;
  gap: 4px;
  min-width: 180px;
  padding: 8px;
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  z-index: 40;
}

.crm-mode-switch details > div a {
  border-radius: 10px;
  color: #17345f;
  padding: 9px 10px;
}

.crm-mode-switch a[aria-current="page"] {
  background: #155dfc;
  box-shadow: 0 8px 18px rgba(21, 93, 252, .24);
  color: #ffffff;
}

.crm-mode-switch a:not([aria-current="page"]):hover {
  background: #eef4ff;
  color: #0b3fb8;
}

.ccc-topbar > .crm-mode-switch {
  background: rgba(15, 30, 54, .72);
  border-color: rgba(148, 163, 184, .28);
  box-shadow: none;
  gap: 2px;
  padding: 3px;
}

.ccc-topbar > .crm-mode-switch span {
  color: #9fb2d3;
  font-size: 10px;
  padding-inline: 6px;
}

.ccc-topbar > .crm-mode-switch a {
  color: #dce8ff;
  font-size: 11px;
  padding: 6px 7px;
}

.ccc-topbar > .crm-mode-switch a[aria-current="page"] {
  background: #3f5cf4;
  color: #ffffff;
}

.ccc-topbar > .crm-mode-switch summary {
  color: #9fb2d3;
  font-size: 11px;
  padding: 6px 7px;
}

.crm-next-bridge-control {
  align-items: center;
  background: #eef6ff;
  border: 1px solid #bfdbfe;
  border-radius: 14px;
  color: #17345f;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 12px;
  padding: 10px 12px;
}

.crm-next-bridge-control button,
.crm-next-bridge-control a {
  align-items: center;
  background: #155dfc;
  border: 0;
  border-radius: 10px;
  color: #ffffff;
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-size: 13px;
  font-weight: 900;
  min-height: 34px;
  padding: 8px 12px;
  text-decoration: none;
}

.crm-next-bridge-control button:disabled {
  cursor: default;
  opacity: .72;
}

.crm-next-bridge-control[data-state="creating"] button:disabled {
  cursor: wait;
}

.crm-next-bridge-control span {
  color: #475569;
  font-size: 13px;
  font-weight: 750;
}

.crm-next-bridge-control strong {
  color: #1e40af;
  font-size: 13px;
}

.crm-next-bridge-control[data-state="created"] {
  background: #ecfdf5;
  border-color: #bbf7d0;
}

.crm-next-bridge-control[data-state="created"] span {
  color: #166534;
}

.crm-next-bridge-control[data-state="error"],
.crm-next-bridge-control[data-state="held"] {
  background: #fff7ed;
  border-color: #fed7aa;
}

.crm-next-bridge-control[data-state="error"] span,
.crm-next-bridge-control[data-state="held"] span {
  color: #9a3412;
}

.customer-console {
  --customer-bg: #f4f7fb;
  --customer-surface: #ffffff;
  --customer-surface-soft: #f8fafc;
  --customer-border: #dce4ef;
  --customer-text: #0b172d;
  --customer-muted: #64748b;
  --customer-blue: #1264e8;
  --customer-shadow: 0 8px 24px rgba(26, 50, 83, .06);
  min-height: 100vh;
  color: var(--customer-text);
  background:
    radial-gradient(circle at 45% -20%, rgba(37, 99, 235, .08), transparent 35%),
    var(--customer-bg);
  font-family: "Segoe UI", sans-serif;
}

.customer-console[data-theme="dark"] {
  --customer-bg: #071321;
  --customer-surface: #101f31;
  --customer-surface-soft: #14253a;
  --customer-border: #26384e;
  --customer-text: #f3f7fc;
  --customer-muted: #9aa9bd;
  --customer-blue: #3b82f6;
  --customer-shadow: 0 12px 30px rgba(0, 0, 0, .2);
  background:
    radial-gradient(circle at 48% -12%, rgba(29, 78, 216, .16), transparent 38%),
    var(--customer-bg);
}

body.customer-console-shell .app-sidebar {
  color: #e9f0f9;
  background: linear-gradient(180deg, #061426 0%, #071a30 55%, #06172a 100%);
  border-color: rgba(148, 163, 184, .14);
}
body.customer-console-shell .sidebar-brand,
body.customer-console-shell .sidebar-link,
body.customer-console-shell .sidebar-account { color: #dce7f5; }
body.customer-console-shell .sidebar-group-label,
body.customer-console-shell .sidebar-store,
body.customer-console-shell .sidebar-account-copy span { color: #8192a9; }
body.customer-console-shell .sidebar-link:hover { background: #13263c; }
body.customer-console-shell .sidebar-link-active { color: #fff; background: #1554bd; }
body.customer-console-shell .sidebar-link-parent-current { color:#dce7f5;background:#13263c }
body.customer-console-shell .sidebar-account { border-color: #25374c; }
body.customer-console-dark-shell .app-sidebar {
  color: #e9f0f9;
  background: #071525;
  border-color: #25374c;
}
body.customer-console-dark-shell .sidebar-brand,
body.customer-console-dark-shell .sidebar-link,
body.customer-console-dark-shell .sidebar-account { color: #dce7f5; }
body.customer-console-dark-shell .sidebar-group-label,
body.customer-console-dark-shell .sidebar-store,
body.customer-console-dark-shell .sidebar-account-copy span { color: #8192a9; }
body.customer-console-dark-shell .sidebar-link:hover { background: #13263c; }
body.customer-console-dark-shell .sidebar-link-active { color: #fff; background: #1554bd; }
body.customer-console-dark-shell .sidebar-link-parent-current { color:#dce7f5;background:#13263c }
body.customer-console-dark-shell .sidebar-account { border-color: #25374c; }

.customer-console button,
.customer-console input { font: inherit; }
.customer-console button { color: inherit; }
.customer-console-toolbar {
  position: sticky;
  top: 0;
  z-index: 15;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 62px;
  padding: 9px 22px;
  background: color-mix(in srgb, var(--customer-surface) 94%, transparent);
  border-bottom: 1px solid var(--customer-border);
  backdrop-filter: blur(14px);
}
.customer-console-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(590px, 48vw);
  min-height: 40px;
  padding: 0 13px;
  color: var(--customer-muted);
  background: var(--customer-surface-soft);
  border: 1px solid var(--customer-border);
  border-radius: 8px;
}
.customer-console-search input { flex: 1; min-width: 0; color: var(--customer-text); background: transparent; border: 0; outline: 0; }
.customer-console-search input::placeholder { color: var(--customer-muted); }
.customer-console-search kbd { font-size:11.5px; color: var(--customer-muted); }
.customer-module-switcher { display:flex;align-items:center;gap:3px;padding:3px;background:var(--customer-surface-soft);border:1px solid var(--customer-border);border-radius:8px }
.customer-module-switcher a { min-height:29px;padding:0 9px;display:flex;align-items:center;color:var(--customer-muted);border-radius:5px;font-size:11.5px;font-weight:700;text-decoration:none;white-space:nowrap }
.customer-module-switcher a.active { color:var(--customer-text);background:var(--customer-surface);box-shadow:0 2px 7px rgba(15,23,42,.1) }
.customer-theme-switch { display: flex; padding: 3px; margin-left: auto; background: var(--customer-surface-soft); border: 1px solid var(--customer-border); border-radius: 9px; }
.customer-theme-option { display: flex; align-items: center; gap: 5px; min-height: 31px; padding: 0 10px; color: var(--customer-muted) !important; background: transparent; border: 0; border-radius: 6px; cursor: pointer; font-size:11.5px !important; font-weight: 700 !important; }
.customer-theme-option.active { color: var(--customer-text) !important; background: var(--customer-surface); box-shadow: 0 2px 7px rgba(15, 23, 42, .1); }
.customer-quick-action { display: flex; align-items: center; gap: 7px; min-height: 38px; padding: 0 16px; color: #fff !important; background: var(--customer-blue); border: 0; border-radius: 7px; cursor: pointer; font-size: 12px !important; font-weight: 700 !important; }
.customer-console-user { display: flex; align-items: center; gap: 8px; min-width: 154px; }
.customer-console-user > span { display: grid; width: 32px; height: 32px; place-items: center; color: #fff; background: #8a4d2c; border-radius: 50%; font-size:11.5px; font-weight: 800; }
.customer-console-user div { display: grid; line-height: 1.25; }
.customer-console-user strong { font-size:11.5px; }
.customer-console-user small { color: var(--customer-muted); font-size:11.5px; }

.customer-console-layout { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 12px; padding: 12px; }
.customer-console-main { min-width: 0; }
.customer-profile-card,
.customer-metric-grid article,
.customer-panel,
.customer-selected-workspace,
.customer-insight-grid article,
.customer-rail-card {
  background: var(--customer-surface);
  border: 1px solid var(--customer-border);
  box-shadow: var(--customer-shadow);
}
.customer-profile-card { display: grid; grid-template-columns: auto minmax(260px, 1.25fr) minmax(430px, 1.8fr) auto; align-items: center; gap: 16px; min-height: 112px; padding: 14px 16px; border-radius: 11px; }
.customer-avatar { position: relative; display: grid; width: 76px; height: 76px; place-items: center; color: #fff; background: linear-gradient(145deg, #c68a68, #203a5f); border: 4px solid var(--customer-surface-soft); border-radius: 50%; }
.customer-avatar span { font-size: 20px; font-weight: 800; }
.customer-avatar i { position: absolute; right: 0; bottom: 4px; width: 12px; height: 12px; background: #22c55e; border: 2px solid var(--customer-surface); border-radius: 50%; }
.customer-profile-identity > div { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.customer-profile-identity h1 { margin: 0; font-size: 20px; letter-spacing: -.02em; }
.customer-profile-identity p { margin: 9px 0 6px; color: var(--customer-muted); font-size:11.5px; }
.customer-profile-identity p b { padding: 0 6px; }
.customer-profile-identity small { color: var(--customer-muted); font-size:11.5px; }
.customer-preferred { display: inline-flex; align-items: center; gap: 5px; padding: 5px 8px; color: var(--customer-text); background: var(--customer-surface-soft); border: 1px solid var(--customer-border); border-radius: 6px; font-size:11.5px; }
.customer-preferred svg { color: #f59e0b; }
.customer-profile-facts { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; margin: 0; }
.customer-profile-facts div { display: grid; gap: 8px; }
.customer-profile-facts dt { color: var(--customer-muted); font-size:11.5px; }
.customer-profile-facts dd { display: flex; align-items: center; gap: 6px; margin: 0; font-size:11.5px; font-weight: 700; }
.customer-mini-avatar { display: grid; width: 20px; height: 20px; place-items: center; color: #fff; background: #8a4d2c; border-radius: 50%; font-size:11.5px; }
.customer-active-dot { width: 8px; height: 8px; background: #22c55e; border-radius: 50%; box-shadow: 0 0 0 3px rgba(34,197,94,.12); }
.customer-icon-button { display: grid; width: 32px; height: 32px; place-items: center; background: var(--customer-surface-soft); border: 1px solid var(--customer-border); border-radius: 7px; }

.customer-metric-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; margin-top: 8px; }
.customer-metric-grid article { display: flex; gap: 10px; min-height: 82px; padding: 13px; border-radius: 10px; }
.customer-metric-grid article > div { display: grid; align-content: center; gap: 3px; }
.customer-metric-grid small { color: var(--customer-muted); font-size:11.5px; }
.customer-metric-grid strong { font-size: 18px; }
.customer-metric-grid p { margin: 0; color: var(--customer-muted); font-size:11.5px; }
.customer-risk-metric strong { color: #ef4444; }
.customer-metric-icon { display: grid; flex: 0 0 30px; width: 30px; height: 30px; place-items: center; border-radius: 50%; }
.customer-metric-icon.green { color: #16a34a; background: #eaf9ef; }.customer-metric-icon.red { color: #ef4444; background: #fff0f0; }.customer-metric-icon.purple { color: #7c3aed; background: #f4edff; }.customer-metric-icon.blue { color: #0284c7; background: #e9f7ff; }.customer-metric-icon.orange { color: #f59e0b; background: #fff6e5; }
[data-theme="dark"] .customer-metric-icon { background: rgba(255,255,255,.06); }

.customer-record-tabs { display: flex; align-items: center; gap: 7px; min-height: 48px; margin-top: 6px; padding: 0 4px; overflow-x: auto; border-bottom: 1px solid var(--customer-border); }
.customer-record-tabs button { position: relative; flex: 0 0 auto; min-height: 47px; padding: 0 12px; color: var(--customer-muted); background: transparent; border: 0; cursor: pointer; font-size:11.5px; font-weight: 600; }
.customer-record-tabs button.active { color: var(--customer-blue); }
.customer-record-tabs button.active::after { position: absolute; right: 6px; bottom: -1px; left: 6px; height: 2px; background: var(--customer-blue); content: ""; }
.customer-overview-grid { display: grid; grid-template-columns: 1.1fr 1fr 1fr; gap: 8px; margin-top: 8px; }
.customer-panel { display: flex; flex-direction: column; min-height: 350px; padding: 13px; border-radius: 10px; }
.customer-panel header,.customer-rail-card header { display: flex; align-items: center; justify-content: space-between; min-height: 27px; padding-bottom: 10px; border-bottom: 1px solid var(--customer-border); }
.customer-panel header strong,.customer-rail-card header strong { font-size:11.5px; }
.customer-panel header button { display: flex; align-items: center; gap: 3px; color: var(--customer-muted); background: transparent; border: 0; font-size:11.5px; }
.customer-timeline { display: grid; gap: 0; }
.customer-timeline > div { position: relative; display: grid; grid-template-columns: 16px 1fr auto; gap: 7px; min-height: 51px; align-items: center; }
.customer-timeline > div:not(:last-child)::before { position: absolute; top: 31px; bottom: -12px; left: 6px; width: 1px; background: var(--customer-border); content: ""; }
.customer-timeline-dot { z-index: 1; width: 12px; height: 12px; background: #22c55e; border: 3px solid color-mix(in srgb, #22c55e 20%, var(--customer-surface)); border-radius: 50%; }
.customer-timeline-dot.tone-1 { background: #f59e0b; }.customer-timeline-dot.tone-2 { background: #3b82f6; }
.customer-timeline div div { display: grid; gap: 4px; }
.customer-timeline strong,.customer-open-items strong { font-size:11.5px; }.customer-timeline small,.customer-open-items small { color: var(--customer-muted); font-size:11.5px; }
.customer-timeline time,.customer-open-items time { color: var(--customer-muted); font-size:11.5px; }
.customer-panel-footer { min-height: 32px; margin-top: auto; color: var(--customer-blue) !important; background: transparent; border: 1px solid var(--customer-border); border-radius: 6px; cursor: pointer; font-size:11.5px !important; font-weight: 700 !important; }
.customer-open-items { display: grid; gap: 7px; padding-top: 9px; }
.customer-open-items > button { display: grid; grid-template-columns: 12px 1fr auto auto; align-items: center; gap: 7px; min-height: 57px; padding: 8px; text-align: left; background: var(--customer-surface-soft); border: 1px solid var(--customer-border); border-radius: 7px; }
