  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
  align-items: end;
}

.manager-review-inline-button {
  width: 100%;
}

.manager-review-inline-span {
  grid-column: 1 / -1;
}

.manager-review-note {
  display: grid;
  gap: 0.35rem;
  padding: 0.9rem 1rem;
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 18px;
  background: rgba(248, 250, 252, 0.92);
}

.manager-review-note span {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.manager-review-note p {
  margin: 0;
  color: var(--ink);
}

.manager-review-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.manager-review-notice {
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.manager-review-columns {
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1.15fr) minmax(260px, 0.7fr);
}

.manager-review-attention-groups {
  display: grid;
  gap: 1rem;
}

.manager-review-bucket {
  display: grid;
  gap: 0.85rem;
  padding: 1rem;
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 22px;
  background: rgba(248, 250, 252, 0.92);
}

.manager-review-bucket-header {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.manager-review-bucket-actions {
  display: grid;
  justify-items: end;
  gap: 0.5rem;
}

.manager-review-bucket-header h4,
.manager-review-bucket-header p {
  margin: 0;
}

.manager-review-bucket-header h4 {
  color: var(--ink);
  font-size: 1rem;
}

.manager-review-bucket-header p {
  margin-top: 0.25rem;
  color: var(--muted);
}

.manager-review-bucket-link {
  min-height: 2.1rem;
  padding: 0.45rem 0.8rem;
  font-size: 0.82rem;
}

.manager-review-empty-inline {
  padding: 0.95rem 1rem;
}

.manager-review-empty-inline p {
  margin: 0;
}

.manager-review-rail-actions {
  display: grid;
  gap: 0.75rem;
  margin-top: 1rem;
}

/* Manager Review Command Center */
.app-topbar-manager-review { display: none; }
.app-topbar-manager-review + .app-content { padding: 0; }

.manager-review-command-center {
  --manager-command-bg: #f4f7fb;
  --manager-command-surface: #ffffff;
  --manager-command-surface-soft: #f8fafc;
  --manager-command-border: #dce4ef;
  --manager-command-border-strong: #c8d3e1;
  --manager-command-text: #101b2e;
  --manager-command-muted: #64748b;
  --manager-command-blue: #1559cf;
  --manager-command-blue-soft: #eaf2ff;
  min-height: 100vh;
  padding: 14px;
  color: var(--manager-command-text);
  background: var(--manager-command-bg);
}

.manager-command-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 2px 2px 12px;
}

.manager-command-title { display: grid; gap: 5px; }
.manager-command-title h1 { margin: 0; color: var(--manager-command-text); font-size: 24px; letter-spacing: -.03em; }
.manager-command-live-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-live-state { display: inline-flex; align-items: center; gap: 6px; color: #176b39; font-weight: 800; }
.manager-command-live-state i { width: 7px; height: 7px; background: #20a657; border-radius: 50%; box-shadow: 0 0 0 3px rgba(32,166,87,.12); }
.manager-command-header-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 8px; }

.manager-command-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 36px;
  padding: 0 11px;
  color: #174b9b;
  background: #fff;
  border: 1px solid #b9cbea;
  border-radius: 6px;
  font: inherit;
  font-size:11.5px;
  font-weight: 800;
  cursor: pointer;
}

.manager-command-button:hover:not(:disabled) { border-color: #7da5e4; background: #f5f9ff; }
.manager-command-button:disabled { color: #8a98ab; background: #f3f6f9; border-color: #d6dee8; cursor: not-allowed; }
.manager-command-button-primary { color: #fff; background: var(--manager-command-blue); border-color: var(--manager-command-blue); }
.manager-command-button-primary:hover:not(:disabled) { color: #fff; background: #1049ad; border-color: #1049ad; }

.manager-command-toolbar {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(150px, .28fr) minmax(150px, .28fr);
  gap: 9px;
  padding: 10px;
  background: var(--manager-command-surface);
  border: 1px solid var(--manager-command-border);
  border-radius: 7px 7px 0 0;
}

.manager-command-toolbar label,
.manager-command-intervention-grid label,
.manager-command-reassign-panel label { display: grid; gap: 5px; color: #52647a; font-size:11.5px; font-weight: 800; }
.manager-command-toolbar input,
.manager-command-toolbar select,
.manager-command-intervention-grid input,
.manager-command-intervention-grid select,
.manager-command-reassign-panel select {
  width: 100%;
  min-height: 36px;
  padding: 0 10px;
  color: var(--manager-command-text);
  background: #fff;
  border: 1px solid #d4deea;
  border-radius: 6px;
  font: inherit;
  font-size:11.5px;
}
.manager-command-search > div { position: relative; }
.manager-command-search svg { position: absolute; top: 10px; left: 10px; color: #7a8a9f; }
.manager-command-search input { padding-left: 34px; }

.manager-command-critical-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  color: #8f1720;
  background: #fffafb;
  border: 1px solid #efc3c7;
  border-top: 0;
}
.manager-command-critical-alert > div { display: flex; align-items: center; gap: 9px; }
.manager-command-critical-alert p { display: grid; gap: 2px; margin: 0; }
.manager-command-critical-alert strong { font-size:11.5px; }
.manager-command-critical-alert span { color: #855058; font-size:11.5px; }
.manager-command-text-action,
.manager-command-text-link { display: inline-flex; align-items: center; gap: 4px; padding: 0; color: #1559cf; background: transparent; border: 0; font: inherit; font-size:11.5px; font-weight: 800; cursor: pointer; }

.manager-command-summary {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  margin-top: 10px;
  background: var(--manager-command-surface);
  border: 1px solid var(--manager-command-border);
  border-radius: 7px;
}
.manager-command-summary button {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 10px 12px;
  color: var(--manager-command-text);
  text-align: left;
  background: transparent;
  border: 0;
  border-right: 1px solid var(--manager-command-border);
  cursor: pointer;
}
.manager-command-summary button:last-child { border-right: 0; }
.manager-command-summary button:hover:not(:disabled),
.manager-command-summary button[aria-pressed="true"] { background: #f2f7ff; box-shadow: inset 0 -2px 0 var(--manager-command-blue); }
.manager-command-summary button:disabled { cursor: not-allowed; opacity: .68; }
.manager-command-summary strong { font-size: 22px; line-height: 1; }
.manager-command-summary span { overflow: hidden; color: #25354b; font-size:11.5px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-summary small { overflow: hidden; color: var(--manager-command-muted); font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-success-notice { margin: 10px 0 0; border-radius: 7px; box-shadow: none; }

.manager-review-command-layout {
  display: grid;
  grid-template-columns: 180px minmax(440px, 1.18fr) minmax(360px, .92fr);
  margin-top: 10px;
  background: var(--manager-command-surface);
  border: 1px solid var(--manager-command-border);
  border-radius: 7px;
  overflow: clip;
}
.manager-review-command-layout > * { min-width: 0; }
.manager-review-command-queue-rail,
.manager-review-command-worklist { border-right: 1px solid var(--manager-command-border); }
.manager-review-command-queue-rail { background: #f8fafc; }

.manager-command-pane-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 58px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--manager-command-border);
}
.manager-command-pane-heading > div { display: grid; gap: 3px; }
.manager-command-pane-heading strong { color: var(--manager-command-text); font-size:11.5px; text-transform: uppercase; letter-spacing: .04em; }
.manager-command-pane-heading span { color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-order-label { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }

.manager-command-queue-list { display: grid; padding: 4px 0; }
.manager-command-queue-button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 7px;
  min-height: 52px;
  padding: 8px 10px;
  color: #28384d;
  text-align: left;
  background: transparent;
  border: 0;
  border-left: 3px solid transparent;
  font: inherit;
  cursor: pointer;
}
.manager-command-queue-button:hover:not(:disabled) { background: #eef4fc; }
.manager-command-queue-button[aria-pressed="true"] { color: #134da7; background: #e7f0ff; border-left-color: var(--manager-command-blue); }
.manager-command-queue-button:disabled { color: #8390a1; cursor: not-allowed; }
.manager-command-queue-button span { overflow: hidden; font-size:11.5px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-queue-button strong { font-size:11.5px; }
.manager-command-queue-button small { grid-column: 1 / -1; overflow: hidden; color: #758397; font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }

.manager-command-work-rows { display: grid; }
.manager-review-command-work-row {
  display: grid;
  grid-template-columns: minmax(190px, 1.6fr) minmax(105px, .72fr) minmax(92px, .68fr) minmax(88px, .62fr) 72px;
  gap: 8px 10px;
  align-items: center;
  width: 100%;
  padding: 10px 11px;
  color: var(--manager-command-text);
  text-align: left;
  background: #fff;
  border: 0;
  border-bottom: 1px solid var(--manager-command-border);
  font: inherit;
  cursor: pointer;
}
.manager-review-command-work-row:hover { background: #f7faff; }
.manager-review-command-work-row[aria-pressed="true"] { background: #f1f6ff; box-shadow: inset 3px 0 0 var(--manager-command-blue); }
.manager-review-command-work-row > span { min-width: 0; }
.manager-command-work-main,
.manager-command-work-owner,
.manager-command-due,
.manager-command-evidence-state { display: grid; gap: 3px; }
.manager-command-work-main strong { overflow: hidden; color: #1251b2; font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-work-main small,
.manager-command-work-owner small,
.manager-command-due small,
.manager-command-evidence-state small { overflow: hidden; color: var(--manager-command-muted); font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-work-owner strong,
.manager-command-due strong,
.manager-command-evidence-state strong { overflow: hidden; font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-due-danger strong { color: #c62b2b; }
.manager-command-due-warning strong { color: #ad5b08; }
.manager-command-priority { display: inline-flex; align-items: center; justify-content: center; min-height: 27px; padding: 0 7px; border: 1px solid; border-radius: 5px; font-size:11.5px; font-style: normal; font-weight: 900; letter-spacing: .03em; text-transform: uppercase; white-space: nowrap; }
.manager-command-priority-critical { color: #bd2029; background: #fff7f7; border-color: #ef8f94; }
.manager-command-priority-high { color: #b45309; background: #fffaf1; border-color: #efb569; }
.manager-command-priority-medium { color: #174d9e; background: #f4f8ff; border-color: #8bb0e8; }
.manager-command-priority-low { color: #53657c; background: #f8fafc; border-color: #cbd5e1; }
.manager-command-work-reason { grid-column: 1 / -1; display: flex; align-items: flex-start; gap: 6px; color: #52647a; font-size:11.5px; line-height: 1.4; }
.manager-command-work-reason svg { flex: 0 0 auto; margin-top: 1px; color: #326bc2; }

.manager-review-command-workbench { background: #fff; }
.manager-command-workbench-inner { display: grid; align-content: start; min-height: 100%; }
.manager-command-selected-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 15px 14px 12px; border-bottom: 1px solid var(--manager-command-border); }
.manager-command-selected-header > div { display: grid; gap: 4px; }
.manager-command-selected-header > div > span { color: #1559cf; font-size:11.5px; font-weight: 900; letter-spacing: .06em; text-transform: uppercase; }
.manager-command-selected-header h2 { margin: 0; color: var(--manager-command-text); font-size: 20px; letter-spacing: -.025em; }
.manager-command-selected-header p { margin: 0; color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-decision-prompt { display: grid; gap: 4px; padding: 11px 14px; background: #f8fbff; border-bottom: 1px solid var(--manager-command-border); }
.manager-command-decision-prompt span { color: var(--manager-command-muted); font-size:11.5px; font-weight: 900; letter-spacing: .06em; text-transform: uppercase; }
.manager-command-decision-prompt strong { font-size:11.5px; line-height: 1.45; }
.manager-command-workbench-meta { display: grid; grid-template-columns: 1fr 1fr; border-bottom: 1px solid var(--manager-command-border); }
.manager-command-workbench-meta > div { display: grid; gap: 3px; padding: 10px 14px; border-right: 1px solid var(--manager-command-border); border-bottom: 1px solid var(--manager-command-border); }
.manager-command-workbench-meta > div:nth-child(even) { border-right: 0; }
.manager-command-workbench-meta > div:nth-last-child(-n+2) { border-bottom: 0; }
.manager-command-workbench-meta span { color: var(--manager-command-muted); font-size:11.5px; font-weight: 800; text-transform: uppercase; }
.manager-command-workbench-meta strong { font-size:11.5px; }
.manager-command-workbench-meta small { color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-workbench-section { display: grid; gap: 9px; padding: 12px 14px; border-bottom: 1px solid var(--manager-command-border); }
.manager-command-workbench-section > p { margin: 0; color: #394b62; font-size:11.5px; line-height: 1.55; }
.manager-command-section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.manager-command-section-heading > div { display: grid; gap: 3px; }
.manager-command-section-heading strong { font-size:11.5px; letter-spacing: .04em; text-transform: uppercase; }
.manager-command-section-heading span { color: var(--manager-command-muted); font-size:11.5px; }

.manager-command-requirement-list { display: grid; margin: 0; padding: 0; border: 1px solid var(--manager-command-border); border-radius: 6px; list-style: none; overflow: hidden; }
.manager-command-requirement-list li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 8px 9px; border-bottom: 1px solid var(--manager-command-border); }
.manager-command-requirement-list li:last-child { border-bottom: 0; }
.manager-command-requirement-list li > span { display: grid; gap: 2px; min-width: 0; }
.manager-command-requirement-list strong { overflow: hidden; font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-requirement-list small { overflow: hidden; color: var(--manager-command-muted); font-size:11.5px; text-overflow: ellipsis; white-space: nowrap; }
.manager-command-requirement-list em { color: var(--manager-command-muted); font-size:11.5px; font-style: normal; font-weight: 800; }
.manager-command-requirement-list .is-complete svg { color: #1b8a4b; }
.manager-command-requirement-list .is-missing svg,
.manager-command-requirement-list .is-missing em { color: #c62b2b; }
.manager-command-configuration-gap { display: flex; align-items: flex-start; gap: 7px; padding: 9px; color: #53657c; background: #f8fafc; border: 1px solid var(--manager-command-border); border-radius: 6px; }
.manager-command-configuration-gap svg { flex: 0 0 auto; }
.manager-command-configuration-gap p { margin: 0; font-size:11.5px; line-height: 1.45; }

.manager-command-explanation { display: grid; gap: 5px; margin: 12px 14px; padding: 10px 11px; background: #f5f8fd; border-left: 3px solid var(--manager-command-blue); }
.manager-command-explanation span { color: #5c6c80; font-size:11.5px; font-weight: 900; letter-spacing: .04em; text-transform: uppercase; }
.manager-command-explanation strong { font-size:11.5px; line-height: 1.45; }
.manager-command-explanation p { margin: 0; color: var(--manager-command-muted); font-size:11.5px; line-height: 1.45; }

.manager-command-action-warning { display: flex; align-items: flex-start; gap: 7px; margin: 0 14px 8px; padding: 8px 9px; color: #9c4a08; background: #fff8ed; border: 1px solid #efd2aa; border-radius: 6px; font-size:11.5px; }
.manager-command-action-warning svg { flex: 0 0 auto; }
.manager-command-action-bar { position: sticky; bottom: 0; z-index: 2; display: flex; flex-wrap: wrap; gap: 6px; padding: 10px 14px; background: rgba(255,255,255,.97); border-top: 1px solid var(--manager-command-border); }
.manager-command-action-bar .manager-command-button { min-height: 34px; padding-inline: 9px; font-size:11.5px; }
.manager-command-inline-notice { margin: 0 14px 12px; border-radius: 6px; box-shadow: none; }

.manager-command-reassign-panel,
.manager-command-intervention { display: grid; gap: 9px; margin: 0 14px 12px; padding: 10px; background: #f8fafc; border: 1px solid var(--manager-command-border); border-radius: 6px; }
.manager-command-reassign-panel { grid-template-columns: minmax(110px, .7fr) minmax(150px, 1fr) auto; align-items: end; }
.manager-command-reassign-panel > div { display: grid; gap: 3px; align-self: center; }
.manager-command-reassign-panel > div strong { font-size:11.5px; text-transform: uppercase; }
.manager-command-reassign-panel > div span { color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-error { grid-column: 1 / -1; margin: 0; color: #b42318; font-size:11.5px; }
.manager-command-intervention-grid { display: grid; grid-template-columns: minmax(160px, 1fr) auto; gap: 8px; align-items: end; }
.manager-command-intervention-wide { grid-column: 1 / -1; }
.manager-command-intervention .manager-command-action-bar { position: static; margin: 0 -10px -10px; padding: 9px 10px; background: transparent; }

.manager-command-no-results,
.manager-command-no-selection { display: grid; justify-items: center; gap: 5px; padding: 42px 18px; color: var(--manager-command-muted); text-align: center; }
.manager-command-no-results strong,
.manager-command-no-selection strong { color: var(--manager-command-text); font-size:11.5px; }
.manager-command-no-results span,
.manager-command-no-selection span { font-size:11.5px; }

.manager-command-health { display: none; margin-top: 10px; padding: 13px; background: #fff; border: 1px solid var(--manager-command-border); border-radius: 7px; }
.manager-command-health.is-open { display: grid; gap: 10px; }
.manager-command-health-header span { color: #1559cf; font-size:11.5px; font-weight: 900; letter-spacing: .05em; text-transform: uppercase; }
.manager-command-health-header h2 { margin: 3px 0 0; font-size: 17px; }
.manager-command-health-header p { margin: 4px 0 0; color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-health-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.manager-command-health-grid article { display: grid; gap: 5px; padding: 9px; background: #f8fafc; border: 1px solid var(--manager-command-border); border-radius: 6px; }
.manager-command-health-grid article > div { display: flex; justify-content: space-between; gap: 8px; }
.manager-command-health-grid article strong,
.manager-command-health-grid article span { font-size:11.5px; }
.manager-command-health-grid article p { margin: 0; color: #465970; font-size:11.5px; }
.manager-command-health-grid article small { color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-footer { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 9px 2px 0; color: var(--manager-command-muted); font-size:11.5px; }
.manager-command-footer span { display: inline-flex; align-items: center; gap: 5px; }

@media (max-width: 1440px) {
  .manager-review-command-layout { grid-template-columns: 165px minmax(400px, 1.08fr) minmax(335px, .92fr); }
  .manager-review-command-work-row { grid-template-columns: minmax(175px, 1.5fr) minmax(90px, .68fr) minmax(86px, .65fr) 70px; }
  .manager-command-evidence-state { display: none; }
}

@media (max-width: 1180px) {
  .manager-command-summary { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .manager-command-summary button:nth-child(4) { border-right: 0; }
  .manager-command-summary button:nth-child(-n+4) { border-bottom: 1px solid var(--manager-command-border); }
  .manager-review-command-layout { grid-template-columns: 170px minmax(0, 1fr); }
  .manager-review-command-worklist { border-right: 0; }
  .manager-review-command-workbench { grid-column: 1 / -1; border-top: 1px solid var(--manager-command-border); }
  .manager-command-health-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .manager-review-command-center { padding: 9px; }
  .manager-command-header { flex-direction: column; }
  .manager-command-header-actions { width: 100%; justify-content: flex-start; }
  .manager-command-toolbar { grid-template-columns: 1fr 1fr; }
  .manager-command-search { grid-column: 1 / -1; }
  .manager-command-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .manager-command-summary button { border-bottom: 1px solid var(--manager-command-border); }
  .manager-command-summary button:nth-child(even) { border-right: 0; }
  .manager-command-critical-alert { align-items: flex-start; flex-direction: column; }
  .manager-review-command-layout { grid-template-columns: minmax(0, 1fr); }
  .manager-review-command-queue-rail,
