/* Activity feed */
.activity-page { max-width: 980px; margin: 0 auto; }
.activity-feed-panel { overflow: hidden; background: #fff; border: 1px solid #e1e7ef; border-radius: 7px; box-shadow: 0 3px 12px rgba(27,45,72,.035); }
.activity-feed-panel-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px; border-bottom: 1px solid #edf0f4; }
.activity-feed-panel-header > div { display: grid; gap: 2px; }
.activity-feed-panel-header h2 { margin: 0; color: #182336; font-size: 12px; }
.activity-feed-panel-header span { color: #6b788b; font-size:11.5px; }
.activity-feed-panel-header select { min-width: 112px; height: 31px; padding: 0 8px; color: #253449; background: #fff; border: 1px solid #dce3ec; border-radius: 5px; font-size:11.5px; }
.activity-feed-list { display: grid; }
.activity-feed-item { display: grid; grid-template-columns: 50px 22px minmax(0,1fr); gap: 7px; padding: 10px 11px; border-bottom: 1px solid #edf0f4; }
.activity-feed-item:last-child { border-bottom: 0; }
.activity-feed-item time { padding-top: 3px; color: #6b788b; font-size:11.5px; font-weight: 800; text-align: right; white-space: nowrap; }
.activity-feed-marker { display: grid; place-items: center; width: 22px; height: 22px; color: #075ad9; background: #eaf2ff; border-radius: 50%; }
.activity-feed-item-danger .activity-feed-marker { color: #df2339; background: #fff1f3; }
.activity-feed-item-warning .activity-feed-marker { color: #e26c08; background: #fff5eb; }
.activity-feed-item-review .activity-feed-marker { color: #6332a8; background: #f4effc; }
.activity-feed-item-success .activity-feed-marker { color: #20804b; background: #eaf7ef; }
.activity-feed-item-system .activity-feed-marker { color: #44546b; background: #f1f5f9; }
.activity-feed-copy { min-width: 0; display: grid; gap: 4px; }
.activity-feed-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.activity-feed-heading strong { color: #202b3a; font-size:11.5px; }
.activity-feed-heading span { color: #68778d; font-size:11.5px; white-space: nowrap; }
.activity-feed-copy p { margin: 0; color: #4f5f73; font-size:11.5px; line-height: 1.45; }
.activity-feed-context { width: fit-content; max-width: 100%; overflow: hidden; color: #075ad9; font-size:11.5px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }
.activity-feed-footer { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 9px 11px; border-top: 1px solid #edf0f4; }
.activity-feed-footer a,.activity-feed-footer button,.activity-feed-error button { display: inline-flex; align-items: center; gap: 5px; color: #075ad9; background: transparent; border: 0; font-size:11.5px; font-weight: 800; cursor: pointer; }
.activity-feed-state { display: grid; justify-items: center; gap: 8px; padding: 17px 14px; color: #68768a; text-align: center; font-size:11.5px; }
.activity-feed-state p { margin: 0; line-height: 1.45; }
.activity-feed-error { color: #a8152c; background: #fff7f8; }
.activity-feed-spinner { width: 22px; height: 22px; border: 3px solid #dbe8fa; border-top-color: #075ad9; border-radius: 50%; animation: board-spin .7s linear infinite; }
.activity-feed-panel-compact { box-shadow: none; }
.activity-feed-panel-compact .activity-feed-item { grid-template-columns: 46px 22px minmax(0,1fr); padding: 9px 10px; }
.activity-feed-panel-compact .activity-feed-footer { padding: 9px 10px; }

/* Manager review queue */
.review-queue-card > header > div { display: grid; gap: 2px; }
.review-queue-card > header span { color: #6332a8; }
.review-queue-list { display: grid; gap: 7px; padding: 0 9px 10px; }
.review-queue-item { display: grid; gap: 8px; padding: 9px; border: 1px solid #eadffb; border-radius: 6px; background: #fbf8ff; }
.review-queue-item-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.review-queue-item-top > div { display: grid; gap: 2px; min-width: 0; }
.review-queue-item-top strong { color: #202b3a; font-size:11.5px; line-height: 1.3; }
.review-queue-item-top span { color: #68778d; font-size:11.5px; }
.review-queue-item-top b { flex: 0 0 auto; padding: 4px 6px; color: #6332a8; background: #f0e9fb; border-radius: 4px; font-size:11.5px; text-transform: uppercase; }
.review-queue-muted-badge { color: #44546b !important; background: #f1f5f9 !important; }
.review-queue-item dl { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 5px; margin: 0; }
.review-queue-item dt { color: #778498; font-size:11.5px; font-weight: 800; text-transform: uppercase; }
.review-queue-item dd { margin: 2px 0 0; color: #253449; font-size:11.5px; font-weight: 800; }
.review-queue-reference,.review-queue-ready-at,.review-queue-error,.review-queue-empty p { margin: 0; color: #68778d; font-size:11.5px; line-height: 1.4; }
.review-queue-reference { color: #334155; }
.review-queue-actions { display: grid; grid-template-columns: 1fr 1fr auto; gap: 5px; align-items: center; }
.review-queue-actions button,.review-queue-actions a { display: inline-flex; align-items: center; justify-content: center; min-height: 27px; padding: 0 8px; border-radius: 4px; font-size:11.5px; font-weight: 800; cursor: pointer; }
.review-queue-actions button:first-child { color: #fff; background: #075ad9; border: 1px solid #075ad9; }
.review-queue-actions button:nth-child(2) { color: #334155; background: #fff; border: 1px solid #dce3ec; }
.review-queue-actions button:disabled { opacity: .62; cursor: wait; }
.review-queue-actions a { color: #075ad9; background: #fff; border: 1px solid #9dc0f7; }
.review-queue-error { padding: 7px; color: #a8152c; background: #fff1f3; border-radius: 5px; }
.review-queue-empty { display: grid; gap: 4px; padding: 13px 12px 14px; }
.review-queue-empty strong { color: #263347; font-size:11.5px; }

@media (max-width: 720px) {
  .activity-feed-panel-header { align-items: stretch; flex-direction: column; }
  .activity-feed-panel-header select { width: 100%; }
  .activity-feed-item { grid-template-columns: 1fr; gap: 6px; }
  .activity-feed-item time { text-align: left; }
  .activity-feed-marker { display: none; }
  .activity-feed-heading { align-items: flex-start; flex-direction: column; gap: 2px; }
  .activity-feed-heading span { white-space: normal; }
}

