/* Shared collaboration composer */
.rich-text-composer {
  position: relative;
  display: grid;
  overflow: visible;
  width: 100%;
  border: 1px solid #cfd9e8;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 8px 22px rgb(15 35 65 / 6%);
}

.rich-text-toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 5px 7px;
  overflow-x: auto;
  border-top: 1px solid #e4eaf2;
  scrollbar-width: thin;
}

.rich-text-toolbar button,
.rich-text-emoji-menu button {
  display: inline-grid;
  flex: 0 0 auto;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  color: #45556e;
  border: 0;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
}

.rich-text-toolbar button:hover:not(:disabled),
.rich-text-toolbar button:focus-visible,
.rich-text-emoji-menu button:hover,
.rich-text-emoji-menu button:focus-visible {
  color: #174dc7;
  outline: none;
  background: #eaf1ff;
}

.rich-text-toolbar button:disabled {
  cursor: not-allowed;
  opacity: .4;
}

.rich-text-toolbar-divider {
  flex: 0 0 1px;
  align-self: stretch;
  margin: 3px 4px;
  background: #dce4ef;
}

.rich-text-toolbar .rich-text-preview-toggle {
  margin-left: auto;
}

.rich-text-toolbar-trailing {
  display: inline-flex;
  flex: 0 0 auto;
  margin-left: auto;
}

.rich-text-composer textarea {
  width: 100%;
  min-height: 82px;
  padding: 10px 12px;
  color: #12233f;
  border: 0;
  border-radius: 0;
  outline: none;
  background: transparent;
  resize: vertical;
  font: inherit;
  font-size: 13px;
  line-height: 1.5;
