/* Enterprise task resolution workbench */
.enterprise-task-workbench {
  --etw-navy: #061a36;
  --etw-blue: #2b50e6;
  --etw-line: #dce4ef;
  --etw-muted: #66758b;
  min-height: calc(100vh - 3.5rem);
  color: #142239;
  background: #f4f7fb;
  border: 1px solid #d8e1ed;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 18px 46px rgba(20, 38, 68, 0.1);
  display: grid;
  grid-template-columns: 154px minmax(0, 1fr);
}

.app-frame:has(.enterprise-task-workbench) { grid-template-columns: 1fr; }
.app-frame:has(.enterprise-task-workbench) > .app-sidebar { display: none; }
.app-frame:has(.etw-simple-workbench) { grid-template-columns: 228px minmax(0, 1fr); }
.app-frame:has(.etw-simple-workbench) > .app-sidebar { display: flex; }
.etw-command-bar,
.etw-module-nav,
.etw-breadcrumb,
.etw-task-action-bar,
.etw-layout { grid-column: 2; }
.etw-local-sidebar { grid-column: 1; grid-row: 1 / 6; display: flex; flex-direction: column; min-height: 100vh; padding: 12px 7px; color: #dbe7f8; background: linear-gradient(180deg, #071c39, #06172f); }
.etw-local-brand { display: flex; align-items: center; gap: 7px; padding: 7px 8px 15px; color: #fff; font-size: 12px; }
.etw-local-sidebar nav { display: grid; gap: 3px; }
.etw-local-sidebar a { display: flex; align-items: center; gap: 9px; min-height: 34px; padding: 0 9px; color: #e4edf9; border-radius: 5px; font-size:11.5px; font-weight: 700; text-decoration: none; }
.etw-local-sidebar a:hover,
.etw-local-sidebar a.active { color: #fff; background: linear-gradient(135deg, #1764e9, #5841f0); }
.etw-local-sidebar > section { display: grid; gap: 2px; margin-top: auto; padding: 10px 5px; background: rgba(255,255,255,.055); border-radius: 8px; }
.etw-local-sidebar > section > strong { padding: 0 5px 5px; color: #fff; font-size:11.5px; }
.etw-local-sidebar > section a { min-height: 29px; font-size:11.5px; }

.etw-command-bar,
.etw-module-nav,
.etw-breadcrumb,
.etw-record-heading,
.etw-card h2,
.etw-resolution-card > header,
.etw-resolution-row,
.etw-command-actions,
.etw-brand,
.etw-search,
.etw-owner,
.etw-resolution-row > span {
