  align-items: center;
}

.etw-command-bar {
  min-height: 48px;
  padding: 6px 14px;
  gap: 18px;
  color: #fff;
  background: radial-gradient(circle at 76% -140%, #214a82, transparent 46%), var(--etw-navy);
}

.etw-brand { gap: 9px; min-width: 205px; }
.etw-brand div { display: grid; gap: 1px; }
.etw-brand strong { font-size: 13px; letter-spacing: 0.03em; text-transform: uppercase; }
.etw-brand span { color: #aebdd1; font-size:11.5px; letter-spacing: 0.06em; text-transform: uppercase; }
.etw-search-shell { position: relative; flex: 1; max-width: 620px; }
.etw-search { flex: 1; max-width: 620px; gap: 7px; min-height: 32px; padding: 0 11px; color: #66758b; background: #fff; border-radius: 7px; }
.etw-search input { width: 100%; padding: 0; border: 0; outline: 0; font-size: 12px; }
.etw-search-shell .etw-search { max-width: none; }
.etw-search-results { position: absolute; top: calc(100% + 7px); right: 0; left: 0; z-index: 40; display: grid; gap: 3px; padding: 7px; color: #16243a; background: #fff; border: 1px solid #cfdced; border-radius: 8px; box-shadow: 0 18px 44px rgba(10, 25, 55, .24); }
