  .etw-simple-summary-facts { grid-template-columns: 1fr; }
  .etw-compact-task-card { grid-template-columns: 1fr; padding: 0; }
  .etw-compact-status-rail { grid-row: auto; grid-template-columns: auto auto 1fr auto; justify-items: start; min-height: 74px; padding: 14px; text-align: left; }
