  .etw-compact-task-body { padding: 17px 15px; border-right: 0; }
  .etw-compact-task-header h1 { font-size: 19px; }
  .etw-compact-title-row strong { font-size: 17px; }
  .etw-compact-signals { grid-column: auto; padding: 15px; border-top: 1px solid #dfe7f1; border-right: 0; }
  .etw-compact-card-menu { display: none; }
  .etw-compact-task-fields,
  .etw-compact-next-action { grid-template-columns: 1fr; }
  .etw-compact-task-utility-row { grid-template-columns: 1fr; }
  .etw-compact-people-control,
  .etw-compact-task-schedule-strip {
    justify-self: stretch;
  }
  .etw-compact-task-fields { gap: 9px; }
  .etw-compact-owner-row,
  .etw-compact-collaborator-row > div { grid-template-columns: 1fr; }
  .etw-compact-task-fields div,
  .etw-compact-task-fields div + div { padding: 0; border-right: 0; }
  .etw-compact-task-links { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .etw-compact-task-links button { justify-content: flex-start; white-space: normal; }
  .etw-compact-task-links button:last-child { grid-column: 1 / -1; }
  .etw-layout { grid-template-columns: 1fr; }
  .etw-context-rail { border-right: 0; border-bottom: 1px solid var(--etw-line); }
  .etw-resolution-row { grid-template-columns: 18px 24px minmax(0, 1fr) 72px; padding-block: 7px; }
  .etw-resolution-row .etw-owner,
