  .etw-resolution-row > span:nth-of-type(5) { display: none; }
  .etw-lifecycle { overflow-x: auto; grid-template-columns: repeat(7, 95px); }
  .etw-command-rail { grid-template-columns: 1fr; }
}

.task-workspace-shell {
