/* Enterprise Appointment Board shell */
.appointment-board-page {
  --appointment-module-rail-width: 52px;
  --appointment-detail-rail-width: clamp(224px, 17vw, 272px);
  --appointment-workspace-sidebar-width: clamp(260px, 18vw, 324px);
  --appointment-calendar-hour-height: 26px;
  --appointment-calendar-grid-height: calc(var(--appointment-calendar-hour-height) * 10);
  --appointment-main-gap: 8px;
  display: grid;
  gap: 7px;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  max-width: 1760px;
  margin: 0 auto;
  padding-left: var(--appointment-module-rail-width);
  color: #111827;
}

.appointment-board-page.appointment-module-rail-expanded {
  --appointment-module-rail-width: 132px;
}

@media (max-width: 1180px) {
  .task-delivery-schedule-row {
    grid-template-columns: 26px repeat(2, minmax(0, 1fr));
  }

  .task-delivery-notes-field,
  .task-delivery-remove-button {
    grid-column: 2 / -1;
  }
}

.appointment-mockup-aligned {
  gap: 5px;
}

.appointment-mockup-aligned > :not(.appointment-module-rail) {
  width: calc(100% - var(--appointment-module-rail-width));
  justify-self: start;
}

.appointment-board-simplified {
  padding-left: 0;
}

.appointment-board-simplified.appointment-mockup-aligned > :not(.appointment-module-rail) {
  width: 100%;
}

.appointment-board-simplified.appointment-mockup-aligned > .appointment-enterprise-shell {
  width: 100%;
}

.appointment-mockup-aligned > .appointment-metric-grid,
.appointment-mockup-aligned > .appointment-upcoming-card {
  width: calc(
    100% - var(--appointment-module-rail-width) - var(--appointment-detail-rail-width) - var(--appointment-main-gap)
  );
}

.appointment-mockup-aligned > .appointment-board-toolbar,
.appointment-mockup-aligned > .appointment-date-row {
  width: calc(100% - var(--appointment-module-rail-width));
}

.appointment-enterprise-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  min-width: 0;
}

.appointment-workspace-open .appointment-enterprise-shell {
  grid-template-columns: minmax(0, 1fr);
}

@media (min-width: 1181px) {
