.workspace-mockup-reference header { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:10px 13px; color:#243b5e; }
.workspace-mockup-reference header>span:first-child { display:grid; gap:2px; }
.workspace-mockup-reference header strong { font-size:11.5px; }
.workspace-mockup-reference header small { color:#6b7c95; font-size:11.5px; }
.workspace-mockup-reference-action { color:#175fe6; font-size:11.5px; font-weight:850; }
.workspace-mockup-reference-body { display:grid; grid-template-columns:minmax(0,1fr) 240px; gap:12px; align-items:center; padding:0 13px 13px; }
.workspace-mockup-reference-body img { display:block; width:100%; height:auto; max-height:none; object-fit:contain; object-position:top; border:1px solid #afc0d8; border-radius:8px; background:#071b37; }
.workspace-mockup-reference-body p { margin:0; color:#5d708b; font-size:11.5px; line-height:1.5; }
.dashboard-page .workspace-mockup-reference { margin:0; }
.workspace-reference-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px; }
.workspace-reference-card { display:grid; gap:0; overflow:hidden; border:1px solid #cbd8e8; border-radius:14px; background:#fff; box-shadow:0 10px 28px rgb(31 58 97 / 8%); }
.workspace-reference-card>a { display:block; background:#071b37; }
.workspace-reference-card>a>img { display:block; width:100%; height:420px; object-fit:contain; object-position:top; background:#071b37; }
.workspace-reference-card>div { display:grid; gap:6px; padding:13px 15px 15px; }
.workspace-reference-card span { color:#526985; font-size:11.5px; font-weight:800; text-transform:uppercase; letter-spacing:.07em; }
.workspace-reference-card h2 { margin:0 0 4px; color:#162a48; font-size:16px; }
.workspace-reference-card .pill { justify-self:start; }
@media (max-width:760px) { .workspace-mockup-reference { margin:0 10px; }.workspace-mockup-reference-body { grid-template-columns:1fr; }.workspace-mockup-reference-action { white-space:nowrap; } }

/* Technician role workspace */
.technician-shift-gate {
  min-height: calc(100vh - 210px);
  display: grid;
  place-items: center;
  padding: 32px;
}

.technician-shift-gate > section {
  width: min(620px, 100%);
  padding: 44px;
  border: 1px solid #d8e1ef;
  border-radius: 26px;
  background: radial-gradient(circle at top right, rgb(67 97 238 / 10%), transparent 34%), #fff;
  box-shadow: 0 22px 60px rgb(15 35 64 / 11%);
  text-align: center;
}

.technician-shift-gate-icon {
  width: 68px;
  height: 68px;
  margin: 0 auto 18px;
  display: grid;
  place-items: center;
  border-radius: 20px;
  color: #fff;
  background: linear-gradient(145deg, #17315f, #4565df);
  box-shadow: 0 14px 28px rgb(45 74 185 / 23%);
}

.technician-shift-gate h1 {
  margin: 8px 0 10px;
  color: #10213e;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.05;
}

.technician-shift-gate > section > p {
  max-width: 470px;
  margin: 0 auto 24px;
  color: #5b6c87;
  font-size: 1.05rem;
  line-height: 1.6;
}

.technician-shift-primary {
  min-height: 52px;
  padding-inline: 24px;
  font-size: 1rem;
}

.technician-shift-separation {
  margin-top: 28px;
  padding: 16px 18px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
  border: 1px solid #d8e7db;
  border-radius: 14px;
  color: #365543;
  background: #f4fbf5;
  text-align: left;
  line-height: 1.45;
}

.technician-shift-separation svg {
  flex: 0 0 auto;
  margin-top: 2px;
}

.technician-shift-status,
.technician-shift-unavailable {
  margin: 18px 20px 0;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 18px;
  border: 1px solid #d6e2dc;
  border-radius: 16px;
  color: #234c34;
  background: #f4fbf6;
}

.technician-shift-status > div:first-child {
  display: grid;
  grid-template-columns: auto auto;
  align-items: center;
  gap: 2px 10px;
}

.technician-shift-status span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #597164;
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.technician-shift-status strong {
  font-size: 1rem;
}

.technician-shift-status small {
  grid-column: 2;
  color: #61756a;
}

.technician-shift-status-actions {
  margin-left: auto;
  display: flex;
  gap: 9px;
}

.technician-shift-status button,
.technician-shift-unavailable button {
  min-height: 38px;
  padding: 8px 13px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #c5d4cb;
  border-radius: 10px;
  color: #183d2a;
  background: #fff;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.technician-shift-status button:disabled,
.technician-shift-unavailable button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.technician-shift-status > p {
  margin: 0;
  color: #8b4b16;
  font-size: 0.86rem;
}

.technician-shift-unavailable {
  border-color: #eed7ae;
  color: #75490f;
  background: #fffaf0;
}

.technician-shift-unavailable > div {
  flex: 1;
}

.technician-shift-unavailable p {
  margin: 3px 0 0;
  color: #765f3e;
  line-height: 1.4;
}

.technician-shift-error {
  margin: 18px auto 0 !important;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: #a33131 !important;
}

.workspace-switcher {
  position: relative;
  flex: 0 0 auto;
}

.workspace-switcher-trigger {
  min-height: 36px;
  max-width: 210px;
  padding: 0 11px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid rgb(139 163 203 / 38%);
  border-radius: 9px;
  color: #e8f1ff;
  background: rgb(23 49 86 / 72%);
  font: inherit;
  font-size: 0.78rem;
  font-weight: 750;
  cursor: pointer;
}

.workspace-switcher-trigger span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-switcher-menu {
  position: absolute;
  z-index: 80;
  top: calc(100% + 10px);
  left: 0;
  width: min(360px, calc(100vw - 32px));
  padding: 9px;
  display: grid;
  gap: 5px;
  border: 1px solid #ccd8e8;
  border-radius: 14px;
  color: #172a46;
  background: #fff;
  box-shadow: 0 22px 55px rgb(8 25 49 / 24%);
}

.workspace-switcher-menu header {
  padding: 8px 9px 10px;
  display: grid;
  gap: 3px;
  border-bottom: 1px solid #e1e7f0;
}

.workspace-switcher-menu header strong {
  font-size: 0.92rem;
}

.workspace-switcher-menu header span {
  color: #677890;
  font-size: 0.75rem;
}

.workspace-switcher-menu > button {
  width: 100%;
  padding: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 10px;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.workspace-switcher-menu > button:hover,
.workspace-switcher-menu > button.active {
  border-color: #cbd9ef;
  background: #f2f6fd;
}

.workspace-switcher-menu > button > span {
  flex: 1;
  display: grid;
  gap: 3px;
}

.workspace-switcher-menu > button strong {
  font-size: 0.82rem;
}

.workspace-switcher-menu > button small {
  color: #687992;
  font-size: 0.72rem;
  line-height: 1.35;
}

.workspace-switcher-menu > p {
  margin: 4px 8px;
  color: #a13434;
  font-size: 0.75rem;
}

@media (max-width: 1100px) {
  .workspace-switcher-trigger span {
    display: none;
  }
}

.technician-assignment-panel,
.technician-available-work-page,
.technician-repair-workbench {
  color: #102441;
}

.technician-assignment-panel {
  display: grid;
  gap: 16px;
  margin: 20px 20px 0;
  padding: 22px;
  border: 1px solid #ccdaeb;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 14px 38px rgb(24 54 92 / 9%);
}

.technician-assignment-panel > header,
.technician-page-header,
.technician-workbench-header,
