  font-size: 14px;
  line-height: 1.45;
  resize: vertical;
}

.technician-update-card textarea:focus {
  border-color: #397fe8;
  outline: 3px solid rgb(57 127 232 / 14%);
}

.technician-exception-fields {
  padding: 0 13px 13px;
  border: 1px solid #f2c7a1;
  border-radius: 9px;
  background: #fff9f3;
}

.technician-update-card footer {
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid #e1e8f0;
}

.technician-update-card footer > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #667b92;
  font-size:11.5px;
}

.technician-submit-exception {
  background: #c76b19;
}

.technician-workbench-rail > section {
  scroll-margin-top: 20px;
}

.technician-workbench-rail dl {
  display: grid;
  gap: 0;
  margin: 13px 0 0;
}

.technician-workbench-rail dl div {
  display: grid;
  grid-template-columns: 90px 1fr;
  gap: 8px;
  padding: 8px 0;
  border-top: 1px solid #e5ebf2;
  font-size: 12px;
}

.technician-workbench-rail dt {
  color: #71839a;
}

.technician-workbench-rail dd {
  margin: 0;
  color: #223e5b;
  font-weight: 750;
}

.technician-workbench-rail ul {
  display: grid;
  gap: 8px;
  margin: 13px 0 0;
  padding: 0;
  list-style: none;
}

.technician-workbench-rail li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid #e5ebf2;
  color: #476078;
  font-size:11.5px;
}

.technician-workbench-rail li div {
  display: grid;
  gap: 2px;
}

.technician-workbench-rail li small {
  color: #73859a;
}

.technician-readiness-list li {
  justify-content: flex-start;
  color: #227146;
}

.technician-readiness-list li.warning {
  color: #a25a16;
}

.technician-workbench-unavailable {
  display: grid;
  max-width: 900px;
  margin: 48px auto;
  padding: 34px;
  border-style: solid;
}

.technician-workbench-unavailable > span {
  color: #a0392e;
  font-weight: 850;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.technician-workbench-unavailable p {
  margin: 0;
  color: #60748f;
}

.technician-workbench-unavailable > div {
  display: flex;
  gap: 9px;
}

@media (max-width: 980px) {
  .technician-workbench-grid {
    grid-template-columns: 1fr;
  }

  .technician-workbench-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .technician-now-band,
  .technician-assignment-panel > header,
  .technician-page-header {
    align-items: flex-start;
    flex-wrap: wrap;
  }
}

@media (max-width: 760px) {
  .technician-shift-gate {
    min-height: auto;
    padding: 16px;
  }

  .technician-shift-gate > section {
    padding: 28px 20px;
  }

  .technician-shift-status,
  .technician-shift-unavailable {
    margin-inline: 10px;
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .technician-shift-status-actions {
    width: 100%;
    margin-left: 0;
  }

  .technician-shift-status-actions button {
    flex: 1;
    justify-content: center;
  }

  .technician-assignment-panel,
  .technician-available-work-page,
  .technician-repair-workbench {
    margin: 10px;
    padding: 14px;
  }

  .technician-assignment-card {
    grid-template-columns: 42px 1fr;
  }

  .technician-assignment-open {
    grid-column: 1 / -1;
    justify-content: center;
  }

  .technician-linked-work,
  .technician-shop-pulse,
  .technician-outcome-row,
  .technician-procedure-grid,
  .technician-update-two-column,
  .technician-exception-fields,
  .technician-workbench-rail {
    grid-template-columns: 1fr;
  }

  .technician-shop-pulse > div {
    border-top: 1px solid #dde5ee;
    border-left: 0;
  }

  .technician-update-card footer,
  .technician-next-step,
  .technician-inline-next-step,
  .technician-workbench-header {
    align-items: stretch;
    flex-direction: column;
  }

  .technician-submit-complete,
  .technician-submit-exception {
    width: 100%;
  }
}
@media (max-width:760px) { .workspace-reference-grid { grid-template-columns:1fr; }.workspace-reference-card>a>img { height:300px; } }

