/* Application-wide appearance */
.app-appearance-switch {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  color: #9fb0c3;
  background: #091c32;
  border: 1px solid #29415d;
  border-radius: 7px;
}
.app-appearance-switch button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 27px;
  padding: 0 7px;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 5px;
  cursor: pointer;
  font-size:11.5px;
  font-weight: 800;
}
.app-appearance-switch button:hover { color: #fff; background: #102b48; }
.app-appearance-switch button.active { color: #fff; background: #1c4f85; box-shadow: 0 2px 8px rgba(0,0,0,.2); }

html[data-app-theme="dark"] {
  color-scheme: dark;
  --bg: #071321;
  --bg-strong: #0b1828;
  --surface: #101f31;
  --surface-soft: #14253a;
  --surface-strong: #17283c;
  --ink: #eef4fb;
  --muted: #9aa9bd;
  --line: #26384e;
  --line-strong: #344a64;
  --brand: #3b82f6;
  --brand-strong: #72a7ff;
  --brand-soft: rgba(59,130,246,.17);
  --success-soft: rgba(34,197,94,.13);
  --warning-soft: rgba(249,115,22,.14);
  --danger-soft: rgba(239,68,68,.14);
  --review-soft: rgba(139,92,246,.16);
  --shadow-lg: 0 24px 56px rgba(0,0,0,.24);
  --shadow-md: 0 14px 34px rgba(0,0,0,.2);
}
html[data-app-theme="dark"] body {
  color: var(--ink);
  background: radial-gradient(circle at top left, rgba(37,99,235,.14), transparent 30%), #071321;
}
html[data-app-theme="dark"] .app-frame,
html[data-app-theme="dark"] .app-workspace,
html[data-app-theme="dark"] .app-content,
html[data-app-theme="dark"] .app-content:has(.inventory-control-tower),
html[data-app-theme="dark"] .app-content:has(.parts-operations-page),
html[data-app-theme="dark"] .app-content:has(.dwh-page),
html[data-app-theme="dark"] .app-content:has(.int-r11),
html[data-app-theme="dark"] .app-content:has(.domain-workflow-page),
html[data-app-theme="dark"] .app-content:has(.govops-page),
html[data-app-theme="dark"] .app-content:has(.visual-console-page),
html[data-app-theme="dark"] .app-content:has(.inventory-console-home),
html[data-app-theme="dark"] .app-content:has(.ict-r3),
html[data-app-theme="dark"] .app-content:has(.ict-exact),
html[data-app-theme="dark"] .app-content:has(.add-vehicle-workflow) {
  color: var(--ink);
  background: #071321;
}
html[data-app-theme="dark"] .dispatch-console-header {
  color: var(--ink);
  background: #0d1c2e;
  border-color: var(--line);
}
html[data-app-theme="dark"] .dispatch-console-title h1,
html[data-app-theme="dark"] .dispatch-console-tabs a { color: var(--ink); }
html[data-app-theme="dark"] .dispatch-console-title p { color: var(--muted); }

html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(
  .hero-panel,
  .panel-card,
  .state-card,
  [class$="-card"],
  [class*="-card "],
  [class$="-panel"],
  [class*="-panel "],
  [class$="-table"],
  [class*="-table "],
  [class$="-toolbar"],
  [class*="-toolbar "]
) {
  border-color: var(--line) !important;
  background-color: var(--surface) !important;
  color: var(--ink);
}
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(
  .hero-panel,
  [class$="-hero"],
  [class*="-hero "]
) { background-image: linear-gradient(145deg, #13263b, #0d1c2e) !important; }
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(h1,h2,h3,h4) { color: var(--ink) !important; }
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(p:not([class*="danger"]):not([class*="error"]),small,dt) { color: var(--muted); }
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(input,select,textarea) {
  color: var(--ink) !important;
  background-color: var(--surface-soft) !important;
  border-color: var(--line-strong) !important;
}
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(input,textarea)::placeholder { color: #8293a8; }
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(table,thead,tbody,tr,th,td) { border-color: var(--line) !important; }
html[data-app-theme="dark"] .app-content > :not(.customer-console) :where(th) { color: var(--muted) !important; background-color: var(--surface-soft) !important; }
html[data-app-theme="dark"] .pill-secondary,
html[data-app-theme="dark"] .pill-muted,
html[data-app-theme="dark"] .button-secondary {
  color: var(--ink);
  background: var(--surface-soft);
  border-color: var(--line-strong);
}
html[data-app-theme="dark"] .notice-danger,
html[data-app-theme="dark"] .state-card-danger { background: #2a1720; }
html[data-app-theme="dark"] .notice-success { background: #10291e; }
html[data-app-theme="dark"] .topbar-popover {
  color: var(--ink);
  background: var(--surface);
  border-color: var(--line);
}
html[data-app-theme="dark"] .topbar-popover-link,
html[data-app-theme="dark"] .topbar-search-field,
html[data-app-theme="dark"] .topbar-popover-empty {
  color: var(--ink);
  background: var(--surface-soft);
  border-color: var(--line);
}
html[data-app-theme="dark"] .topbar-popover :where(strong,input) { color: var(--ink); }
html[data-app-theme="dark"] .topbar-popover :where(span,p) { color: var(--muted); }

