.appointment-board-simplified .appointment-week-view,
.appointment-board-simplified .appointment-month-view {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  min-height: 0;
  margin-top: 0;
  padding: 8px;
  background: #fff;
}

.appointment-board-simplified .appointment-week-grid {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 7px;
}

.appointment-board-simplified .appointment-week-view .appointment-section-heading,
.appointment-board-simplified .appointment-month-view .appointment-section-heading {
  padding-bottom: 4px;
}

.appointment-board-simplified .appointment-week-view .appointment-section-heading p,
.appointment-board-simplified .appointment-month-view .appointment-section-heading p {
  display: none;
}

.appointment-board-simplified .appointment-week-column {
  gap: 6px;
  min-height: 136px;
  padding: 8px;
  border-radius: 9px;
  box-shadow: none;
}

.appointment-board-simplified .appointment-week-column-list {
  gap: 5px;
}

.appointment-board-simplified .appointment-week-item {
  gap: 2px;
  min-height: 0;
  padding: 6px 7px;
  background: #fff;
  border-left: 3px solid #2f61d5;
  border-radius: 7px;
  box-shadow: none;
}

.appointment-board-simplified .appointment-week-item strong,
.appointment-board-simplified .appointment-month-item strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.appointment-board-simplified .appointment-month-grid {
  grid-template-columns: repeat(7, minmax(74px, 1fr));
  gap: 5px;
}

.appointment-board-simplified .appointment-month-cell {
  gap: 5px;
  min-height: 82px;
  padding: 6px;
  border-radius: 8px;
  box-shadow: none;
}

.appointment-board-simplified .appointment-month-cell-top span {
  padding: 1px 5px;
  border-radius: 999px;
  background: #eef4ff;
  color: #2559c7;
  font-weight: 900;
}

.appointment-board-simplified .appointment-month-cell-list {
  gap: 4px;
}

.appointment-board-simplified .appointment-month-item {
  min-height: 0;
  padding: 4px 5px;
  border: 0;
  border-left: 3px solid #2f61d5;
  border-radius: 5px;
  background: #f8fbff;
}

.appointment-board-simplified .appointment-month-item:nth-of-type(n + 2) {
  display: none;
}

.appointment-board-simplified .appointment-month-more {
  margin: 0;
}
