/* Today / Action Center */
.app-content:has(.today-action-center) {
  padding: 0;
  background: #f4f7fb;
}

.today-action-center {
  display: grid;
  gap: 14px;
  max-width: 1440px;
  margin: 0 auto;
  padding: 18px;
  color: #13243b;
}

.today-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  border: 1px solid #d8e2ee;
  border-radius: 22px;
  padding: 22px;
  background:
    radial-gradient(circle at 92% 12%, rgb(45 111 222 / 18%), transparent 30%),
    linear-gradient(135deg, #ffffff 0%, #f8fbff 58%, #edf5ff 100%);
  box-shadow: 0 18px 42px rgb(18 35 60 / 9%);
}

.today-hero p {
  margin: 0 0 6px;
  color: #075ed8;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.today-hero h1 {
  margin: 0;
  font-size: clamp(30px, 4vw, 48px);
  line-height: 1.02;
  letter-spacing: -.045em;
}

.today-hero span {
  display: block;
  margin-top: 8px;
  color: #5e7088;
  font-size: 15px;
  line-height: 1.4;
}

.today-start-button {
  display: inline-flex;
  min-width: 190px;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 1px solid #075ed8;
  border-radius: 16px;
  padding: 0 18px;
  color: #fff;
  background: #075ed8;
  font-size: 15px;
  font-weight: 900;
  text-decoration: none;
  box-shadow: 0 16px 30px rgb(7 94 216 / 22%);
}

.today-start-button-calm {
  border-color: #c9d7e8;
  color: #1d3554;
  background: #fff;
  box-shadow: 0 10px 24px rgb(18 35 60 / 9%);
}

.today-kpi-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.today-kpi-strip article {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-height: 98px;
  border: 1px solid #d8e2ee;
  border-radius: 18px;
  padding: 14px;
  background: #fff;
  box-shadow: 0 10px 28px rgb(18 35 60 / 6%);
}

.today-kpi-strip article.attention {
  border-color: #f1c7a3;
  background: #fff8f1;
}

.today-kpi-strip svg {
  grid-row: 1 / 4;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  padding: 10px;
  color: #075ed8;
  background: #eaf3ff;
}

.today-kpi-strip article.attention svg {
  color: #b45309;
  background: #fff0db;
}

.today-kpi-strip span {
  color: #61728a;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.today-kpi-strip strong {
  font-size: 28px;
  line-height: 1;
}

.today-kpi-strip small {
  color: #718198;
  font-size: 12px;
}

.today-primary-grid,
.today-work-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(320px, .8fr);
  gap: 12px;
  align-items: start;
}

.today-work-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.today-panel-wide {
  grid-column: 1 / -1;
}

.today-panel {
  overflow: hidden;
  border: 1px solid #d8e2ee;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 12px 30px rgb(18 35 60 / 7%);
}

.today-panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #e6edf5;
  padding: 14px 16px;
}

.today-panel > header span {
  font-size: 15px;
  font-weight: 950;
}

.today-panel > header a {
  color: #075ed8;
  font-size: 13px;
  font-weight: 900;
  text-decoration: none;
}

.today-card-list {
  display: grid;
  gap: 10px;
  padding: 12px;
}

.today-card-list-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.today-task-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 18px;
  gap: 4px 10px;
  border: 1px solid #dde7f2;
  border-left: 5px solid #7d8da4;
  border-radius: 16px;
  padding: 13px 12px;
  color: #14243c;
  background: #fbfdff;
  text-decoration: none;
}

.today-task-card-danger {
  border-left-color: #dc2626;
  background: #fff8f8;
}

.today-task-card-warning {
  border-left-color: #d97706;
  background: #fffaf0;
}

.today-task-card-review {
  border-left-color: #7c3aed;
  background: #fbf8ff;
}

.today-task-card-ready {
  border-left-color: #0f766e;
  background: #f6fffd;
}

.today-task-card span {
  grid-column: 1;
  color: #64748b;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.today-task-card strong {
  grid-column: 1;
  overflow: hidden;
  font-size: 15px;
  line-height: 1.25;
  text-overflow: ellipsis;
}

.today-task-card small {
  grid-column: 1;
  color: #64748b;
  font-size: 13px;
  line-height: 1.35;
}

.today-task-card svg {
  grid-column: 2;
  grid-row: 1 / 4;
  align-self: center;
  color: #7d8da4;
}

.today-next-card .today-task-card {
  min-height: 142px;
  align-content: center;
  margin: 12px;
}

.today-next-card .today-task-card strong {
  font-size: 20px;
}

.today-quick-actions > div {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 12px;
}

.today-quick-actions a {
  display: grid;
  min-height: 92px;
  align-content: center;
  justify-items: center;
  gap: 8px;
  border: 1px solid #dce6f2;
  border-radius: 16px;
  color: #18304f;
  background: #f8fbff;
  font-size: 14px;
  font-weight: 900;
  text-align: center;
  text-decoration: none;
}

.today-quick-actions a:first-child {
  color: #fff;
  border-color: #075ed8;
  background: #075ed8;
}

.today-empty-card {
  display: grid;
  gap: 8px;
  justify-items: start;
  margin: 12px;
  border: 1px dashed #cbd8e8;
  border-radius: 16px;
  padding: 18px;
  color: #52647c;
  background: #f8fbff;
}

.today-empty-card strong {
  color: #18304f;
  font-size: 16px;
}

.today-empty-card span {
  font-size: 14px;
  line-height: 1.4;
}

.today-empty-card-compact {
  margin: 0;
}

@media (max-width: 960px) {
  .today-kpi-strip {
    display: flex;
    margin-inline: -8px;
    overflow-x: auto;
    padding-inline: 8px;
    scroll-snap-type: x mandatory;
  }

  .today-kpi-strip article {
    flex: 0 0 min(78vw, 280px);
    scroll-snap-align: start;
  }

  .today-primary-grid,
  .today-work-grid,
  .today-card-list-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .app-content:has(.today-action-center) {
    padding-bottom: calc(86px + env(safe-area-inset-bottom));
  }

  .today-action-center {
    gap: 12px;
    padding: 10px 8px 18px;
    overflow-x: clip;
  }

  .today-hero {
    display: grid;
    grid-template-columns: 1fr;
    gap: 14px;
    border-radius: 18px;
    padding: 18px 16px;
  }

  .today-hero h1 {
    font-size: clamp(29px, 8vw, 36px);
  }

  .today-hero p,
  .today-task-card span,
  .today-kpi-strip span {
    font-size: 12px !important;
  }

  .today-hero span,
  .today-empty-card span,
  .today-task-card small {
    font-size: 14px !important;
  }

  .today-start-button {
    position: sticky;
    bottom: max(10px, env(safe-area-inset-bottom));
    z-index: 40;
    width: 100%;
    min-height: 52px;
    border-radius: 16px;
  }

  .today-panel {
    border-radius: 18px;
  }

  .today-panel > header {
    padding: 13px 14px;
  }

  .today-panel > header span {
    font-size: 16px !important;
  }

  .today-panel > header a,
  .today-quick-actions a {
    font-size: 14px !important;
  }

  .today-next-card .today-task-card {
    min-height: 128px;
  }

  .today-next-card .today-task-card strong,
  .today-task-card strong {
    font-size: 17px !important;
  }

  .today-quick-actions > div {
    grid-template-columns: 1fr 1fr;
  }

  .today-quick-actions a {
    min-height: 88px;
  }
