  .review-queue-actions {
    grid-template-columns: 1fr !important;
  }

  .metric-card,
  .appointment-console-kpis article,
  .ich-kpis article,
  .customer-home-metrics article,
  .oc-command-strip article {
    flex-basis: min(86vw, 270px);
  }
}

