  }

  .board-hero-actions {
    display: grid !important;
    grid-template-columns: 1fr !important;
    width: 100%;
  }

  .board-hero .board-toolbar {
    justify-self: stretch;
  }

  .board-hero .board-toolbar-actions > *,
  .appointment-console-hero nav > *,
  .ich-hero-actions > *,
